  "code": "def _validate(self, validators, output, strict=False):
        """Perform schema-level validation. Store errors on the Unmarshaller
        object.
        """
        for validator_func in validators:
            try:
                if not validator_func(output):
                    raise ValidationError(u'Schema validator {0}({1})'.format(
                        validator_func.__name__, dict(output)
                    ))
            except ValidationError as err:
                if strict:
                    raise UnmarshallingError(err)
                # Store errors
                self.errors['_schema'] = text_type(err)
        return output"
